import { render } from '@solidjs/web';
import { createSignal, createMemo, Loading } from 'solid-js';

async function fetchForecast(city) {
  await new Promise((resolve) => setTimeout(resolve, 1500));
  const temps = { Oslo: 4, Lisbon: 21, Tokyo: 16 };
  return { city, temp: temps[city], sky: city === 'Oslo' ? 'Snow' : 'Sunny' };
}

function Forecast(props) {
  const forecast = createMemo(() => fetchForecast(props.city));
  return (
    <p>
      {forecast().city}: {forecast().temp}°C, {forecast().sky}
    </p>
  );
}

function App() {
  const [city, setCity] = createSignal('Oslo');

  return (
    <>
      <h1>Weather</h1>
      <select onChange={(event) => setCity(event.currentTarget.value)}>
        <option>Oslo</option>
        <option>Lisbon</option>
        <option>Tokyo</option>
      </select>
      <Forecast city={city()} />
    </>
  );
}

render(() => <App />, document.getElementById('app'));

